const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),stage=document.getElementById('stage');const ui=id=>document.getElementById(id);const W=400,H=700,R=15,G=1000;let hazards=[],elapsed=0;let platforms=[],ball,camera=0,score=0,best=0,highest=0,playing=false,drag=null,last=0,acc=0;try{best=Number(localStorage.getItem('sky-sling-best'))||0}catch{}ui('best').textContent=best;
function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=stage.clientWidth*d;canvas.height=stage.clientHeight*d}new ResizeObserver(resize).observe(stage);
function reset(){elapsed=0;hazards=[];platforms=[{x:125,y:610,w:150,id:0}];for(let i=1;i<90;i++){const prev=platforms[i-1],w=Math.max(76,120-i*.5);let center=prev.x+prev.w/2+(Math.random()-.5)*170;center=Math.max(w/2+15,Math.min(W-w/2-15,center));platforms.push({x:center-w/2,y:610-i*100,w,id:i})}ball={x:200,y:610-R,vx:0,vy:0,ground:platforms[0]};camera=0;score=0;highest=0;drag=null;acc=0;ui('score').textContent='0';ui('hint').textContent='พร้อม 3 วินาที! ลากลงแล้วปล่อยยิง ฉากจะค่อย ๆ เลื่อนขึ้น ↑'}
function platformType(p){return p.id>0&&p.id%7===0?'spring':p.id%7===4?'fade':'normal'}
function syncHazards(){const known=new Set(hazards.map(h=>h.id));for(const p of platforms){if(p.id<3||p.id%3!==0||known.has(p.id))continue;const center=p.x+p.w/2;hazards.push({id:p.id,x:center<200?310:90,y:p.y+50,r:17,moving:p.id>=6,phase:p.id*1.7})}hazards=hazards.filter(h=>h.y<camera+H+200)}
function hazardX(h){return h.x+(h.moving?Math.sin(elapsed*1.5+h.phase)*42:0)}
function start(){reset();playing=true;ui('overlay').classList.add('hidden')}
function end(reason="ตกแล้ว! 💫"){playing=false;drag=null;ui('overlay').classList.remove('hidden');ui('overlay').innerHTML='<div class="card"><h1>'+reason+'</h1><div class="score">'+score+'</div><p>คะแนนสูงสุด '+best+'<br>ลองเล็งให้ลงกลางแท่น แล้วไปต่อ!</p><button id="again">ลองอีกครั้ง →</button></div>';ui('again').onclick=start}
function point(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height+camera}}
function aim(){let dx=ball.x-drag.x,dy=ball.y-drag.y,len=Math.hypot(dx,dy);if(len>115){dx*=115/len;dy*=115/len}return {vx:dx*5.7,vy:dy*5.7,len:Math.min(len,115)}}
canvas.addEventListener('pointerdown',e=>{if(!playing||!ball.ground||drag)return;const p=point(e);if(Math.hypot(p.x-ball.x,p.y-ball.y)>85)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);drag={...p,id:e.pointerId};ui('hint').textContent='ลากทิศตรงข้ามกับที่จะพุ่ง · ปล่อยเพื่อยิง'});
canvas.addEventListener('pointermove',e=>{if(drag&&drag.id===e.pointerId){e.preventDefault();Object.assign(drag,point(e))}});
canvas.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;Object.assign(drag,point(e));const a=aim();drag=null;if(a.len<10||a.vy>-100){ui('hint').textContent='ลากลงด้านล่าง เพื่อให้ตัวละครพุ่งขึ้น ↑';return}ball.vx=a.vx;ball.vy=a.vy;ball.ground=null;ui('hint').textContent='กำลังลอย… ลงแท่นแล้วเล็งต่อได้เลย'});
canvas.addEventListener('pointercancel',()=>{drag=null});window.addEventListener('blur',()=>{drag=null});
function step(dt){if(!playing)return;elapsed+=dt;if(elapsed>3)camera-=Math.min(32,10+score*.035)*dt;syncHazards();for(const p of platforms){if(p.fadeLeft!==undefined&&!p.gone){p.fadeLeft-=dt;if(p.fadeLeft<=0){p.gone=true;if(ball.ground===p){ball.ground=null;ball.vx=0;ball.vy=0;drag=null;ui('hint').textContent='แท่นหายแล้ว! ระวังตกขอบล่าง'}}}}if(!ball.ground){const oldY=ball.y;ball.vy+=G*dt;ball.x+=ball.vx*dt;ball.y+=ball.vy*dt;if(ball.vy>0){for(const p of platforms){if(!p.gone&&oldY+R<=p.y+1&&ball.y+R>=p.y&&ball.x+R*.65>p.x&&ball.x-R*.65<p.x+p.w){ball.y=p.y-R;ball.vx=0;ball.vy=0;ball.ground=p;if(p.id>highest){highest=p.id;score=highest*10;ui('score').textContent=score;if(score>best){best=score;ui('best').textContent=best;try{localStorage.setItem('sky-sling-best',best)}catch{}}}if(platformType(p)==='fade'){if(p.fadeLeft===undefined)p.fadeLeft=2.4;ui('hint').textContent='แท่นสีส้มกำลังหาย! รีบลากแล้วยิงต่อภายใน 2.4 วินาที'}else if(platformType(p)==='spring'){ball.ground=null;ball.vy=-760;drag=null;const next=platforms.find(q=>q.id===p.id+2&&!q.gone);ball.vx=next?Math.max(-160,Math.min(160,(next.x+next.w/2-ball.x)/1.15)):0;ui('hint').textContent='บูสต์! แท่นสีม่วงเด้งสูงกว่าปกติ 🚀'}else ui('hint').textContent='ลงแท่นแล้ว! รีบเล็งต่อ ฉากกำลังเลื่อนขึ้น ↑';break}}}}if(highest>platforms[platforms.length-1].id-15){for(let n=0;n<30;n++){const prev=platforms[platforms.length-1],id=prev.id+1,w=Math.max(76,120-id*.5),center=Math.max(w/2+15,Math.min(W-w/2-15,prev.x+prev.w/2+(Math.random()-.5)*170));platforms.push({x:center-w/2,y:prev.y-100,w,id})}platforms=platforms.filter(p=>p.y<camera+H+200)}for(const h of hazards){if(Math.hypot(ball.x-hazardX(h),ball.y-h.y)<R+h.r-3){end('ชนลูกหนาม! 💥');return}}const target=ball.y-H*.53;if(target<camera)camera=target;if(ball.y-R>camera+H)end()}
function rounded(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function draw(){ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0);const bg=ctx.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#152544');bg.addColorStop(1,'#376d83');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);for(let i=0;i<38;i++){const x=(i*83+29)%W,y=((i*137-camera*.2)%H+H)%H;ctx.globalAlpha=.25+(i%3)*.15;ctx.fillStyle='white';ctx.beginPath();ctx.arc(x,y,i%3===0?2:1,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.save();ctx.fillStyle='rgba(225,245,255,.10)';ctx.font='900 38px system-ui';ctx.textAlign='center';for(let j=-1;j<5;j++){const labelY=((j*210-camera*.35)%1050+1050)%1050-150;ctx.fillText('HERO × SHOKUN',W/2,labelY)}ctx.restore();for(const p of platforms){const y=p.y-camera;if(p.gone||y<-20||y>H+30)continue;const kind=platformType(p);ctx.globalAlpha=p.fadeLeft!==undefined?Math.max(.12,p.fadeLeft/2.4):1;ctx.fillStyle=kind==='fade'?'#ffb35c':kind==='spring'?'#c79aff':p.id===highest?'#bfe969':'#82c7cc';rounded(p.x,y,p.w,13,6);ctx.fillStyle='#254b61';rounded(p.x+5,y+11,p.w-10,9,4);ctx.fillStyle='#e3f4e9';ctx.font='10px system-ui';ctx.textAlign='center';ctx.fillText(p.id===0?'START':kind==='spring'?'↑↑ BOOST':kind==='fade'?(p.fadeLeft!==undefined?Math.max(0,p.fadeLeft).toFixed(1)+'s':'⌛ FADE'):String(p.id),p.x+p.w/2,y+10);ctx.globalAlpha=1}for(const h of hazards){const y=h.y-camera;if(y<-40||y>H+40)continue;ctx.save();ctx.translate(hazardX(h),y);ctx.rotate(elapsed*.8);ctx.fillStyle='#ff7587';ctx.shadowColor='#ff526d';ctx.shadowBlur=12;ctx.beginPath();for(let k=0;k<24;k++){const a=k*Math.PI/12,r=k%2===0?h.r:h.r*.64;const x=Math.cos(a)*r,yy=Math.sin(a)*r;if(k===0)ctx.moveTo(x,yy);else ctx.lineTo(x,yy)}ctx.closePath();ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#6d263d';ctx.beginPath();ctx.arc(0,0,7,0,Math.PI*2);ctx.fill();ctx.restore()}if(drag&&playing){const a=aim();ctx.strokeStyle='#f6d98c';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(ball.x,ball.y-camera);ctx.lineTo(drag.x,drag.y-camera);ctx.stroke();for(let t=.05;t<1.25;t+=.065){const x=ball.x+a.vx*t,y=ball.y+a.vy*t+.5*G*t*t-camera;ctx.fillStyle='rgba(213,250,116,'+(1-t/1.4)+')';ctx.beginPath();ctx.arc(x,y,3,0,7);ctx.fill()}ctx.fillStyle='#fff';ctx.font='12px system-ui';ctx.fillText('POWER '+Math.round(a.len/115*100)+'%',ball.x,ball.y-camera-32)}ctx.save();ctx.translate(ball.x,ball.y-camera);ctx.fillStyle='#d5fa74';ctx.shadowColor='#d5fa74';ctx.shadowBlur=15;rounded(-R,-R,R*2,R*2,11);ctx.shadowBlur=0;ctx.fillStyle='#153448';rounded(-10,-7,20,12,5);ctx.fillStyle='#e5faff';ctx.fillRect(-6,-3,4,4);ctx.fillRect(3,-3,4,4);ctx.restore()}
function frame(t){if(!last)last=t;acc+=Math.min((t-last)/1000,.05);last=t;while(acc>=1/120){step(1/120);acc-=1/120}draw();requestAnimationFrame(frame)}ui('start').onclick=start;ui('restart').onclick=start;reset();resize();requestAnimationFrame(frame);
